            W(f"  [{tt}] Condition {r['id']}: {r['code']['text']} | recorded={r.get('recordedDate')} by {r.get('recorder',{}).get('display')}")
        elif t=='AllergyIntolerance':
            W(f"  [{tt}] Allergy {r['id']}: {r['code']['text']} | {r.get('reaction',[{}])[0].get('manifestation',[{}])[0].get('text')}")
        elif t=='Specimen':
            a=r['accessionIdentifier']['value']
            W(f"  [{tt}] Specimen {r['id']} acc={a} coll={r['collection']['collectedDateTime']} by {r['collection'].get('collector',{}).get('display')} label: {ext(r,'label-name')} / MRN {ext(r,'label-mrn')} / DOB {ext(r,'label-dob')}")
