                W(f"        ACCESSION {b['id']} acc={a} lab-entry: {ext(b,'patient-name')} / MRN {ext(b,'patient-mrn')} / DOB {ext(b,'patient-dob')} recv={ext(b,'received')} by {b.get('author',{}).get('display')}")
        elif t=='Observation':
            sp=r.get('specimen',{}).get('reference','').split('/')[-1]
            notes=' ; '.join(n['text'] for n in r.get('note',[]))
            W(f"  [{tt}] Obs {r['id']}: {r['code']['text']} status={r['status']} coll={r.get('effectiveDateTime')} issued={r.get('issued')} val={r.get('valueString')!r} acc={(r.get('identifier') or [{}])[0].get('value')} spec={sp}"+(f" NOTE: {notes}" if notes else ""))
        elif t=='MedicationAdministration':
            notes=' ; '.join(n['text'] for n in r.get('note',[]))
            W(f"  [{tt}] MedAdmin {r['id']}: {r['medicationCodeableConcept']['text']} {r['dosage']['text']} status={r['status']} eff={r.get('effectiveDateTime')} by {(r.get('performer') or [{}])[0].get('actor',{}).get('display')}"+(f" NOTE: {notes}" if notes else ""))
        elif t=='MedicationDispense':
            notes=' ; '.join(n['text'] for n in r.get('note',[]))
            W(f"  [{tt}] MedDispense {r['id']}: {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} handed={r.get('whenHandedOver')} sig={(r.get('dosageInstruction') or [{}])[0].get('text')}"+(f" NOTE: {notes}" if notes else ""))
        elif t=='DocumentReference':
            W(f"  [{tt}] Doc {r['id']} type={r['type']['text']} role={ext(r,'author-role')} author={(r.get('author') or [{}])[0].get('display')} date={r.get('date')}")
            for line in r['description'].split('\n'):
                W('        | '+line)
        elif t=='Task':
            W(f"  ** REQUEST {r['id']}: {r['code']['coding'][0]['code']} focus={r.get('focus',{}).get('reference')} :: {r.get('description')}")
        else:
            W('  ?? '+t)
open('dump.txt','w').write('\n'.join(out)+'\n')
print(len(out))
EOF
