import json, collections, datetime as dt, re
E='export/'
def load(f): return [json.loads(l) for l in open(E+f+'.ndjson')]
TYPES=['AllergyIntolerance','Basic','Condition','DocumentReference','EpisodeOfCare','MedicationAdministration','MedicationDispense','Observation','Patient','Specimen','Task']
res={f:load(f) for f in TYPES}
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
def D(s): return dt.date.fromisoformat(s[:10])
EVAL=dt.date(2026,9,24)
pats={p['id']:p for p in res['Patient']}
eps={e['id']:e for e in res['EpisodeOfCare']}
ep_by_p={e['patient']['reference'].split('/')[-1]:e for e in res['EpisodeOfCare']}
spec={s['id']:s for s in res['Specimen']}
byp=collections.defaultdict(lambda: collections.defaultdict(list))
for f,rs in res.items():
    if f in ('Patient','Basic'): continue
    for r in rs:
        s=r.get('subject') or r.get('patient') or r.get('for')
        if s and 'reference' in s: byp[s['reference'].split('/')[-1]][f].append(r)
# specimen owner (by patient subject)
obs_for_spec=collections.defaultdict(list)
for o in res['Observation']:
    sp=o.get('specimen',{}).get('reference','').split('/')[-1]
    obs_for_spec[sp].append(o)

def months_add(d,m):
    y=d.year+(d.month-1+m)//12; mo=(d.month-1+m)%12+1
    day=min(d.day,[31,29 if y%4==0 and (y%100!=0 or y%400==0) else 28,31,30,31,30,31,31,30,31,30,31][mo-1])
    return dt.date(y,mo,day)

rows=[]
for pid,p in sorted(pats.items()):
    ep=ep_by_p[pid]
    dx=D(ep['period']['start'])
    conds=[(D(c['recordedDate']),c['code']['text'],c['id']) for c in byp[pid]['Condition']]
    stages=sorted(set(c[1] for c in conds))
    # treatment
    admins=sorted(byp[pid]['MedicationAdministration'], key=lambda r:r['effectiveDateTime'])
    doses=[(D(a['effectiveDateTime']),a['medicationCodeableConcept']['text'],a['dosage']['text'],a['status'],a['id']) for a in admins]
    disp=[(D(d['whenHandedOver']),d['medicationCodeableConcept']['text'],d.get('daysSupply',{}).get('value'),(d.get('dosageInstruction') or [{}])[0].get('text'),d['id']) for d in byp[pid]['MedicationDispense']]
    # RPR specimens owned by patient
    rpr=[]
    for s in byp[pid]['Specimen']:
        for o in obs_for_spec[s['id']]:
            if o['code']['text']=='RPR, quantitative':
                rpr.append((D(s['collection']['collectedDateTime']), o['status'], o.get('valueString'), o['subject']['reference'].split('/')[-1], s['id'], o['id']))
    rpr.sort()
    hcg=[]
    for s in byp[pid]['Specimen']:
        for o in obs_for_spec[s['id']]:
            if o['code']['text'].startswith('hCG'):
                hcg.append((D(s['collection']['collectedDateTime']), o['code']['text'], o['status'], o.get('valueString'), o['subject']['reference'].split('/')[-1], o['id']))
    hcg.sort()
    rows.append(dict(pid=pid,ep=ep['id'],dx=dx,name=p['name'][0]['text'],gender=p['gender'],stages=stages,conds=conds,doses=doses,disp=disp,rpr=rpr,hcg=hcg))
json.dump([{k:(str(v) if isinstance(v,dt.date) else v) for k,v in r.items()} for r in rows], open('rows.json','w'), default=str)
# summary print
for r in rows:
    print(f"{r['pid']} {r['ep']} dx={r['dx']} {r['gender']:6s} stage={r['stages']}")
    print('   doses:', [(str(d[0]),d[2],d[3]) for d in r['doses']], 'disp:', [(str(d[0]),d[1],d[2]) for d in r['disp']])
    print('   rpr:', [(str(x[0]),x[1],x[2],'FILED:'+x[3] if x[3]!=r['pid'] else '') for x in r['rpr']])
    if r['hcg']: print('   hcg:', [(str(x[0]),x[2],x[3],'FILED:'+x[4] if x[4]!=r['pid'] else '') for x in r['hcg']])
