import json, collections, datetime as dt, re
E='export/'
def load(f): return [json.loads(l) for l in open(E+f+'.ndjson')]
TYPES=['AllergyIntolerance','Basic','Condition','DocumentReference','EpisodeOfCare','MedicationAdministration','MedicationDispense','Observation','Patient','Specimen','Task']
res={f:load(f) for f in TYPES}
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
def D(s): return dt.date.fromisoformat(str(s)[:10])
EVAL=dt.date(2026,9,24)
pats={p['id']:p for p in res['Patient']}
ep_by_p={e['patient']['reference'].split('/')[-1]:e for e in res['EpisodeOfCare']}
spec={s['id']:s for s in res['Specimen']}
accB=collections.defaultdict(list)
for b in res['Basic']: accB[ext(b,'accession')].append(b)
byp=collections.defaultdict(lambda: collections.defaultdict(list))
for f,rs in res.items():
    if f in ('Patient','Basic'): continue
    for r in rs:
        s=r.get('subject') or r.get('patient') or r.get('for')
        if s and 'reference' in s: byp[s['reference'].split('/')[-1]][f].append(r)
obs_for_spec=collections.defaultdict(list)
for o in res['Observation']: obs_for_spec[o.get('specimen',{}).get('reference','').split('/')[-1]].append(o)
def months_add(d,m):
    y=d.year+(d.month-1+m)//12; mo=(d.month-1+m)%12+1
    dim=[31,29 if (y%4==0 and (y%100!=0 or y%400==0)) else 28,31,30,31,30,31,31,30,31,30,31][mo-1]
    return dt.date(y,mo,min(d.day,dim))
tasks=collections.defaultdict(list)
for t in res['Task']:
    if t['status']=='requested': tasks[t['for']['reference'].split('/')[-1]].append(t['code']['coding'][0]['code'])

LATE={'Late latent syphilis','Latent syphilis, unknown duration'}
out=[]
for pid,p in sorted(pats.items()):
    ep=ep_by_p[pid]; dx=D(ep['period']['start'])
    conds=[(D(c['recordedDate']),c['code']['text']) for c in byp[pid]['Condition']]
    stages=sorted(set(c[1] for c in conds))
    late = any(s in LATE for s in stages)
    flags=[]
    if len(stages)>1: flags.append('MULTI_STAGE:'+str(stages))
    if not stages: flags.append('NO_CONDITION')
    admins=sorted([a for a in byp[pid]['MedicationAdministration']], key=lambda r:r['effectiveDateTime'])
    good=[a for a in admins if a['status']=='completed' and 'enzathine' in a['medicationCodeableConcept']['text'] and '2.4' in a['dosage']['text']]
    notdone=[a for a in admins if a['status']!='completed']
    other=[a for a in admins if a not in good and a not in notdone]
    dd=[D(a['effectiveDateTime']) for a in good]
    doxy=[d for d in byp[pid]['MedicationDispense'] if 'oxycycline' in d['medicationCodeableConcept']['text']]
    allergy=byp[pid]['AllergyIntolerance']
    # pregnancy signals
    hcgpos=[]; preg_docs=[]
    for s in byp[pid]['Specimen']:
        for o in obs_for_spec[s['id']]:
            if o['code']['text'].startswith('hCG'):
                if o.get('valueString')=='Positive': hcgpos.append(D(s['collection']['collectedDateTime']))
                if o['status']=='registered': flags.append('HCG_PENDING:'+str(D(s['collection']['collectedDateTime'])))
    for d in byp[pid]['DocumentReference']:
        txt=d['description']
        if re.search(r'pregnan|gestat|prenatal|postpartum|deliver|obstetric|EDD|weeks|G\dP\d|trimester|infant|cesarean',txt,re.I) or d['type']['text'] in ('Prenatal visit','Postpartum visit','Prenatal intake'):
            preg_docs.append((d['id'],d['type']['text'],ext(d,'author-role'),txt.replace('\n',' | ')))
    # RPR collections owned by patient
    coll=[]
    for s in byp[pid]['Specimen']:
        a=s['accessionIdentifier']['value']
        bs=accB.get(a,[])
        lab_ok = any(ext(b,'patient-mrn')==ext(s,'label-mrn') and str(ext(b,'patient-dob'))==str(ext(s,'label-dob')) for b in bs)
        for o in obs_for_spec[s['id']]:
            if o['code']['text']=='RPR, quantitative':
                coll.append(dict(date=D(s['collection']['collectedDateTime']),status=o['status'],val=o.get('valueString'),filed=o['subject']['reference'].split('/')[-1],spec=s['id'],obs=o['id'],labok=lab_ok,nbasic=len(bs)))
    # obs filed in this chart w/ specimen of other patient
    foreign=[]
    for o in byp[pid]['Observation']:
        sp=o.get('specimen',{}).get('reference','').split('/')[-1]
        s=spec.get(sp)
        if s and s['subject']['reference'].split('/')[-1]!=pid:
            foreign.append((o['id'],o['code']['text'],sp,s['subject']['reference'].split('/')[-1]))
    # follow-up windows
    fu=[]
    if dd:
        t0=dd[0]
        months=[6,12,24] if late else [6,12]
        for m in months:
            due=months_add(t0,m); lo=due-dt.timedelta(days=30); hi=due+dt.timedelta(days=30)
            if hi>=EVAL: continue
            hits=[c for c in coll if lo<=c['date']<=hi and c['status']!='cancelled']
            unres=[c for c in coll if lo<=c['date']<=hi and c['status']!='cancelled' and not c['labok']]
            fu.append((m,str(due),len(hits),len(unres),[str(c['date'])+':'+c['status'] for c in coll if lo<=c['date']<=hi]))
    out.append(dict(pid=pid,ep=ep['id'],dx=str(dx),name=p['name'][0]['text'],gender=p['gender'],stages=stages,late=late,
        doses=[str(x) for x in dd], notdone=[(a['id'],a['effectiveDateTime'],a['status'],a['dosage']['text']) for a in notdone],
        otheradmin=[(a['id'],a['effectiveDateTime'],a['medicationCodeableConcept']['text'],a['dosage']['text']) for a in other],
        doxy=[(d['id'],d['whenHandedOver'][:10],d.get('daysSupply',{}).get('value'),(d.get('dosageInstruction') or [{}])[0].get('text')) for d in doxy],
        allergy=[(a['id'],a['code']['text']) for a in allergy], hcgpos=[str(x) for x in hcgpos], preg_docs=preg_docs,
        coll=[{**c,'date':str(c['date'])} for c in coll], foreign=foreign, fu=fu, flags=flags, tasks=tasks.get(pid,[]),
        outside=[(d['id'],d['type']['text'],ext(d,'author-role')) for d in byp[pid]['DocumentReference'] if ext(d,'author-role')=='outside-facility']))
json.dump(out,open('auto.json','w'),indent=0)
print(len(out))
